namespace VSharp.Compiler;

/// <summary>Long-form explanations of every diagnostic code, for 'vsharpc explain'.</summary>
public static class Explain
{
    public sealed record Entry(string Code, string Title, string Text, string? Example = null);

    public static readonly IReadOnlyList<Entry> All =
    [
        new("TN1001", "syntax error",
            "The source does not match V#'s grammar. Every statement starts with a keyword (let, var, ghost, set, if, while, match, return, assert, print, do), every block is in braces, and comparisons cannot be chained.",
            "if 0 <= i && i < n { ... }   // not: if 0 <= i < n"),
        new("TN2001", "unknown name",
            "A type, variable, function, method, field or case name is not declared. V# has no imports: everything a module uses is declared in the module, in the prelude (Option, Some, None, Result, Ok, Err) or is a builtin. ('use Namespace' only shortens .NET attribute names.) A method is found from its receiver's class or interface."),
        new("TN2002", "type mismatch",
            "An expression has a different type from the one required. V# has no implicit conversions: use to_float(i) for Int to Float, trunc(x) for Float to Int, and to_f32/to_f64 between tensor element types.",
            "let x: Float = to_float(n)"),
        new("TN2003", "shape mismatch",
            "Two tensor shapes that must agree are different. Shapes are part of tensor types and are checked at compile time. Dimension parameters are solved from the arguments at each call; dimension expressions such as 'H * W' are compared as polynomials.",
            "fn flatten[B, H, W](x: Tensor[B, H, W]) -> Tensor[B, H * W] { return reshape[B, H * W](x) }"),
        new("TN2004", "duplicate name",
            "Names are unique within a module (types, cases, functions and builtins share one namespace) and within a function (no shadowing). One name, one meaning, so a reader never has to resolve scopes."),
        new("TN2005", "assignment to an immutable variable",
            "'let' declares an immutable variable. Declare it with 'var' to allow 'set'.",
            "var total = 0\nset total = total + 1"),
        new("TN2006", "missing effect",
            "A function performs an effect it does not declare. 'print' and calls to io functions need 'effects io'; calls to device functions need 'effects device'; awaiting an async function needs 'effects async'. Specifications, spec functions and lemmas are pure and cannot have effects.",
            "fn main() -> Unit effects io { print 1 }"),
        new("TN2007", "wrong number of arguments",
            "A call passes a different number of arguments from the number of parameters (or fields, for a constructor)."),
        new("TN2008", "specification-only construct in code",
            "Quantifiers, 'result', 'self', spec functions, lemmas and row_sum describe programs; they cannot run. Use them in requires, ensures, invariant, assert and ghost code only."),
        new("TN2009", "invalid dimension",
            "Tensor dimensions are positive integer literals, dimension parameters, or sums and products of them. A dimension parameter must appear on its own (not inside an expression) in at least one parameter type, so every call determines it."),
        new("TN2010", "missing return",
            "Some path reaches the end of a function that returns a value without a 'return'. Add a final 'return', or make every branch return."),
        new("TN2011", "missing termination measure",
            "Recursive functions (including mutually recursive groups) and while loops need a 'decreases' clause: a non-negative Int, or a list of them compared lexicographically, that every recursive call or iteration makes smaller.",
            "fn ack(m: Int, n: Int) -> Int requires m >= 0 && n >= 0 decreases m, n { ... }"),
        new("TN2012", "mismatched measures",
            "Functions that call each other recursively are proved terminating together, so their 'decreases' clauses must have the same number of components."),
        new("TN2013", "misused construct",
            "A construct is used where it is not allowed: 'main' must take no parameters and return Unit; 'do' needs a call; lemmas are called with 'do'; shape arguments are only for reshape and full; recursion is not allowed through 'requires' or 'decreases'."),
        new("TN2014", "named arguments required",
            "When two or more parameters of a function have the same type, every call must name its arguments, in declaration order. This makes swapped arguments (the commonest silent bug in generated code) impossible. Builtins take positional arguments.",
            "clamp(x: 150, lo: 0, hi: 100)"),
        new("TN2015", "cannot differentiate",
            "'fn g = grad f wrt p' needs 'f' to be an ordinary, non-generic function returning Float, 'p' a Float or tensor parameter, and the body to be straight-line code (let and return; no loops, branches on the differentiated value or non-differentiable builtins)."),
        new("TN2016", "invalid match",
            "A 'match' must cover every case of the union exactly once (or end with '_'), and each pattern binds exactly as many names as the case has fields. Exhaustiveness is checked at compile time, so a new case breaks every match that forgot it.",
            "match r { Ok(v) { return v } Err(_) { return 0 } }"),
        new("TN2017", "invalid extern",
            "'extern fn' binds a public static .NET method or property by its full name. Only Int (long), Float (double), Bool, Unit (void) and arrays of those may cross the boundary, and the .NET signature must match exactly. Extern functions are trusted: their contracts are assumed, not proved.",
            "extern fn sqrt(x: Float) -> Float requires x >= 0.0 ensures result >= 0.0 from \"System.Math.Sqrt\""),
        new("TN2018", "ghost code misuse",
            "Ghost variables and lemma calls exist only for the proof and are erased before code generation. Ghost code cannot assign ordinary variables, return, print or have effects, and executable code cannot read ghost variables."),
        new("TN2019", "missing or invalid trigger",
            "A quantifier over a whole type ('forall x: Int : ...') needs explicit triggers: terms (calls, indexes or field accesses) that mention every bound variable. The solver instantiates the quantifier only for terms matching a trigger, which keeps proofs fast and predictable. Bounded quantifiers ('forall i in 0..n') need none.",
            "forall x: Int trigger f(x) : f(x) >= 0"),
        new("TN2020", "refinement type as a type argument",
            "Refinement types (type Nat = Int where self >= 0) can be used for parameters, results, variables and fields, but not inside other types such as Array[Nat]. State the property with a quantifier instead.",
            "requires forall i in 0..len(a) : a[i] >= 0"),
        new("TN2021", "cannot infer a type",
            "A type parameter or the type of an empty array or hole cannot be determined from the arguments or the expected type. Annotate the variable.",
            "let xs: Array[Int] = []"),
        new("TN2022", "files declare different modules",
            "A multi-file module is compiled from files that all start with the same 'module Name' line. Each file may add 'total' for its own functions.",
            "// a.vs\nmodule Scheduling\n// b.vs\nmodule Scheduling total"),
        new("TN2023", "lambda misuse",
            "Lambdas ('x => e', '(acc, x) => e') are only allowed as arguments of collection builtins (map, filter, any, all, count, find, find_last, sum_by, min_by, max_by, sort_by, sort_by_desc, group_by, to_map, fold). They are inlined, must be pure, and must take the number of parameters the builtin expects.",
            "let big = filter(xs, x => x > 10)"),
        new("TN2024", "break or continue outside a loop",
            "'break' leaves the innermost 'while' or 'for' loop and 'continue' starts its next iteration; neither is allowed outside a loop."),
        new("TN2025", "invalid constant",
            "A 'const' is built from literals, earlier constants, operators, constructors and builtins. It cannot call functions or use a constant declared after it, and cannot have type Unit or Tensor.",
            "const MAX_RETRIES: Int = 3"),
        new("TN2026", "invalid attribute",
            "'@Name(args)' must name a .NET attribute type: its full name, a name under a 'use' namespace, or under System. The 'Attribute' suffix is optional. Arguments are literals, enum members (Enum.Member) and arrays of those; 'name: value' sets a property or field. The attribute's AttributeUsage must allow the target (a record, union or class is a .NET class, an interface an interface, a field a property, a function or method a method). Spec functions, lemmas, externs, refinement types and constants have no .NET form and take no attributes. Types outside the .NET runtime need '--reference <dll>'.",
            "use System.Text.Json.Serialization\ntype Dto = { @JsonPropertyName(\"id\") key: Int }"),
        new("TN2027", "invalid interface implementation",
            "A class implements every method of each interface it lists, with the same name, parameter names, parameter types and result type. An implementation inherits the interface method's 'requires' and 'ensures': it cannot add 'requires' (callers through the interface would not know them), may add 'ensures', and may only have effects the interface method declares.",
            "interface Shape { fn area(self) -> Decimal ensures result > 0m }\nclass Square(side: Decimal) implements Shape {\n  invariant self.side > 0m\n  fn area(self) -> Decimal { return self.side * self.side }\n}"),
        new("TN2028", "recursion through an interface method",
            "A call through an interface can run any implementation, so the verifier cannot bound recursion that passes through one: a method that reaches itself through an interface call (for example a wrapper class holding a value of the same interface) is rejected. Recurse over a union with a module function and a 'decreases' clause instead."),
        new("TN2029", "await misuse",
            "A call to an async function (one with 'effects async') must be awaited, and only such calls can be. 'await' is the whole value of a 'let', 'var', 'set', 'return' or 'do' statement, never part of a larger expression, so every suspension point is a statement.",
            "fn load(s: Store) -> Int effects async { let v = await s.fetch(1)\n  return v }"),
        new("TN2030", "exception misuse",
            "Every exception that can leave a function is caught or declared with 'throws E' (optionally 'when cond'). A call to a function whose clause for E has no 'when' condition must be inside a try block that catches E, or in a function that declares E. Also reported: a catch that nothing in its try block can reach, a catch hidden by an earlier one, throwing from a spec function or lemma, and binding a .NET exception type that would also catch V#'s run-time stops (System.Exception, OverflowException and their bases).",
            "exception Frozen\n\nfn take(a: Account) -> Account\n  throws Frozen when a.frozen\n{ if a.frozen { throw Frozen }\n  return a }"),
        new("TN3001", "postcondition might not hold",
            "The verifier found a path on which an 'ensures' clause is false. The counterexample gives parameter values that reach it. Fix the code, strengthen 'requires', or weaken 'ensures'."),
        new("TN3002", "precondition might not hold",
            "A call might violate the callee's 'requires'. The caller must establish it: check the condition first, or add it to the caller's own 'requires'."),
        new("TN3003", "assertion might not hold", "An 'assert' might be false on some path. Assertions are proved, never checked at run time."),
        new("TN3004", "loop invariant might not hold on entry", "An 'invariant' is false before the first iteration. Check the initial values of the loop variables."),
        new("TN3005", "loop invariant might not be maintained",
            "Assuming the invariants and the condition at the top of an iteration, the body might make an invariant false. Invariants are the only facts carried across iterations, so they often need strengthening."),
        new("TN3006", "possible division by zero", "Prove the divisor is not zero, for example with 'requires d != 0' or an 'if'."),
        new("TN3007", "index might be out of bounds", "Prove 0 <= i && i < len(a) at the access, typically through a loop invariant or 'requires'."),
        new("TN3008", "termination not proved",
            "A recursive call or loop iteration might not decrease the 'decreases' measure, or the measure might be negative. For a lexicographic measure 'a, b', each step must decrease 'a', or keep 'a' and decrease 'b'."),
        new("TN3009", "vacuous preconditions (warning)",
            "The 'requires' clauses contradict each other, so the function can never be called and every claim about it is trivially true."),
        new("TN3010", "array length might be negative", "fill(n, v) needs n >= 0."),
        new("TN3011", "integer overflow possible",
            "In total mode ('module M total', 'fn ... total' or 'vsharpc --total') every Int operation is proved to stay within 64 bits, so the program can never trap. Outside total mode, overflow traps at run time instead."),
        new("TN3012", "tensor dimensions might differ",
            "Two dimension expressions are not identical polynomials, so they must be proved equal from the 'requires' clauses, e.g. 'requires H * W == N'."),
        new("TN3013", "conversion to Int might fail", "trunc(x) needs x to be a number whose integer part fits in 64 bits. Prove a range for x first."),
        new("TN3014", "refinement might not hold",
            "A value passed, returned, stored or assigned where a refinement type is expected might not satisfy its 'where' predicate."),
        new("TN3015", "date might be invalid or out of range",
            "date(y, m, d) needs a real calendar day (1 <= y <= 9999, 1 <= m <= 12, 1 <= d <= days in that month, with leap years), and add_days must stay between 0001-01-01 and 9999-12-31. Check is_valid_date or bound the inputs first.",
            "if is_valid_date(y, m, d) { return Some(date(y, m, d)) }"),
        new("TN3016", "class invariant might not hold",
            "Every construction of a class value, by its constructor or by 'with', must satisfy the class's invariants. Because class values never change, every method and every caller may then assume them. The compiled constructor also checks invariants that do not call functions, so .NET code cannot build an invalid value.",
            "class Range(lo: Int, hi: Int) {\n  invariant self.lo <= self.hi\n}"),
        new("TN3017", "exception condition might not hold",
            "'throws E when cond' promises that E is thrown only when cond held on entry. The verifier proves this at every 'throw' of E and at every call that may let E escape. A call to a function that throws E only under a condition may also go uncaught and undeclared, if the condition is proved false at the call; this error means it might hold. Guard the call, strengthen a precondition, catch the exception, or declare it."),
        new("TN4001", "typed hole",
            "'?name' marks code still to be written. The compiler reports the hole's type, the variables in scope, the facts known at that point, and the obligations a replacement must satisfy, then stops. Fill holes one at a time and re-check.",
            "return ?answer"),
    ];

    public static Entry? Find(string code) => All.FirstOrDefault(e => string.Equals(e.Code, code, StringComparison.OrdinalIgnoreCase));
}
